"""==============================================================================IOTEC111_TIMELINE_ENGINE.py==============================================================================Timeline Operacional=============================================================================="""from __future__ import annotationsimport sqlite3import timefrom pathlib import PathDATABASE = Path("iotec.db")class TimelineEngine:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row    # ==================================================================    def show(self):        print("\033c", end="")        print("=" * 80)        print("IOTEC LIVE TIMELINE")        print("=" * 80)        print()        rows = self.conn.execute("""            SELECT                created_at,                mission_uuid,                agent_uuid,                action,                status,                details            FROM agent_governance            ORDER BY id DESC            LIMIT 30        """).fetchall()        if not rows:            print("SEM EVENTOS")        for r in rows:            print(f"[{r['created_at']}]")            print(f"MISSÃO : {r['mission_uuid']}")            print(f"AGENTE : {r['agent_uuid']}")            print(f"AÇÃO   : {r['action']}")            print(f"STATUS : {r['status']}")            print(f"INFO   : {r['details']}")            print("-" * 80)    # ==================================================================    def monitor(self):        while True:            self.show()            time.sleep(2)# =============================================================================if __name__ == "__main__":    TimelineEngine().monitor()